/* From Uiverse.io by MuhammadHasann - Tags: card */
.__UIV_SCOPE__ .card {
  position: relative;
  background: #fff;
  width: 190px;
  height: 265px;
  border-radius: 8px;
  cursor: pointer;
  transition: all 120ms;
  overflow: hidden;
  box-shadow: 0px 1px 13px rgba(0,0,0,0.1);
}

.__UIV_SCOPE__ .card:active {
  transform: scale(.95);
}

.__UIV_SCOPE__ .card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  box-shadow: inset 0px 0px 25px 5px rgba(255, 255, 255, .5);
  z-index: 1;
}

.__UIV_SCOPE__ .card::after {
  content: "Add to Cart";
  position: absolute;
  bottom: -50%;
  left: 0;
  padding-left: 15px;
  background: #181818;
  width: 100%;
  height: 60px;
  color: #fff;
  line-height: 50px;
  text-transform: uppercase;
  z-index: 2;
  transition: all .2s ease-in;
}

.__UIV_SCOPE__ .card:hover::after {
  bottom: 0;
}

.__UIV_SCOPE__ .card:active::after {
  content: "Adding !";
  height: 65px;
}

.__UIV_SCOPE__ .image {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100px;
  height: auto;
  filter: drop-shadow(3px 3px 5px #18181815);
  transform: translate(-50%, -50%);
  animation: shoes 1s ease infinite alternate;
  transition: all .5s ease-in;
}

@keyframes shoes {
  from {
    top: 48%;
  }

  to {
    top: 52%;
  }
}

.__UIV_SCOPE__ .card:hover .image {
  /* top: 20%;
  left: 30%; */
  width: 220px;
  height: auto;
  animation: none;
  transform: rotate(15deg) translate(-35%, -25%);
}

.__UIV_SCOPE__ .text {
  position: absolute;
  top: 15%;
  left: -80%;
  color: #181818;
  transition: all .3s ease-in;
}

.__UIV_SCOPE__ .text span {
  font-size: 25px;
  font-weight: 400;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .text p {
  font-size: 18px;
  font-weight: bold;
}

.__UIV_SCOPE__ .card:hover .text {
  top: 15%;
  left: 5%;
}

.__UIV_SCOPE__ .fil-shoes2 {
  fill: #a59573
}
